//! BF16×F32 AVX-512 (x86_64, zmm) matmul kernel.
//!
//! Generated by `avx512_matmul_packed!` / `avx512_matmul_packed_tiled!` in
//! `super::super::simd_avx512`.  BF16 weight bytes are unpacked 16 lanes at
//! a time with `_mm512_cvtepu16_epi32` + `_mm512_slli_epi32` (zero-extend
//! and shift into the F32 high half; needs AVX-512BW).  Dispatch prefers
//! this kernel when `n_in % 16 == 0` and falls back to the AVX2 kernel for
//! multiples of 8.

use crate::{avx512_matmul_packed, avx512_matmul_packed_tiled};

#[target_feature(enable = "avx512f", enable = "avx512bw", enable = "fma")]
unsafe fn unpack_bf16_16(w: *const u8, row_byte: usize, col: usize) -> std::arch::x86_64::__m512 {
    use std::arch::x86_64::*;
    let chunk = _mm256_loadu_si256(w.add(row_byte + col * 2) as *const __m256i);
    _mm512_castsi512_ps(_mm512_slli_epi32(_mm512_cvtepu16_epi32(chunk), 16))
}

#[target_feature(enable = "avx512f", enable = "avx512bw", enable = "fma")]
unsafe fn scalar_unpack_bf16(w: *const u8, row_byte: usize, col: usize) -> f32 {
    let bits = u16::from_le_bytes([*w.add(row_byte + col * 2), *w.add(row_byte + col * 2 + 1)]);
    crate::ops::bf16_to_f32(bits)
}

avx512_matmul_packed!(
    matmul_bf16_vs_f32_avx512,
    2,
    unpack_bf16_16,
    scalar_unpack_bf16
);

avx512_matmul_packed_tiled!(
    matmul_bf16_vs_f32_avx512_tiled,
    2,
    unpack_bf16_16,
    scalar_unpack_bf16
);

#[cfg(test)]
mod tests {
    use super::{matmul_bf16_vs_f32_avx512, matmul_bf16_vs_f32_avx512_tiled};
    use crate::ops::kernel::bf16::scalar::forward_f32_rows_scalar;

    fn assert_avx512_eq_scalar(
        label: &str,
        weight: &[u8],
        input: &[f32],
        n_in: usize,
        n_out: usize,
    ) {
        let mut avx512_out = vec![0.0f32; n_out];
        let mut scalar_out = vec![0.0f32; n_out];
        unsafe {
            matmul_bf16_vs_f32_avx512(weight, input, &mut avx512_out, n_in, 0, n_out);
        }
        forward_f32_rows_scalar(weight, input, &mut scalar_out, n_in, n_out, 0, 1);
        for (i, (a, s)) in avx512_out.iter().zip(scalar_out.iter()).enumerate() {
            assert!(
                (a - s).abs() < 1e-2,
                "{} row {}: avx512={} scalar={} diff={}",
                label,
                i,
                a,
                s,
                (a - s).abs(),
            );
        }
    }

    #[test]
    fn avx512_matches_scalar_small() {
        let mut weight = Vec::new();
        for r in 0..4 {
            for c in 0..16 {
                weight.extend(crate::ops::f32_to_bf16((r * 16 + c) as f32 * 0.1).to_le_bytes());
            }
        }
        let input: Vec<f32> = (0..16).map(|i| (i as f32 - 8.0) * 0.05).collect();
        assert_avx512_eq_scalar("small 4x16", &weight, &input, 16, 4);
    }

    #[test]
    fn avx512_matches_scalar_large() {
        let n_in = 256;
        let n_out = 16;
        let mut weight = Vec::new();
        for r in 0..n_out {
            for c in 0..n_in {
                weight.extend(
                    crate::ops::f32_to_bf16((((r * n_in + c) % 37) as f32 - 18.0) * 0.01)
                        .to_le_bytes(),
                );
            }
        }
        let input: Vec<f32> = (0..n_in).map(|i| ((i % 23) as f32 - 11.0) * 0.02).collect();
        assert_avx512_eq_scalar("large 16x256", &weight, &input, n_in, n_out);
    }

    #[test]
    fn avx512_matches_scalar_tail() {
        let n_in = 40;
        let n_out = 3;
        let mut weight = Vec::new();
        for r in 0..n_out {
            for c in 0..n_in {
                weight.extend(
                    crate::ops::f32_to_bf16(((r * n_in + c) as f32 * 0.01).sin()).to_le_bytes(),
                );
            }
        }
        let input: Vec<f32> = (0..n_in).map(|i| i as f32 * 0.03).collect();
        assert_avx512_eq_scalar("tail 3x40", &weight, &input, n_in, n_out);
    }

    /// The tiled kernel must be bit-identical to the per-token kernel: same
    /// dot body, only the loop nesting changes. Shapes cross both the
    /// 32-row and 32-token tile boundaries with `n_in` a multiple of 16.
    #[test]
    fn avx512_tiled_matches_per_token_bits() {
        let n_in = 192usize;
        let n_out = 70usize;
        let rows = 33usize;
        let weight: Vec<u8> = (0..n_in * n_out)
            .flat_map(|i| crate::ops::f32_to_bf16(((i % 41) as f32 - 20.0) / 16.0).to_le_bytes())
            .collect();
        let input: Vec<f32> = (0..rows * n_in)
            .map(|i| (((i * 31 + 7) % 97) as f32 - 48.0) / 32.0)
            .collect();

        let mut expected = vec![0.0f32; rows * n_out];
        for (input_row, output_row) in
            input.chunks_exact(n_in).zip(expected.chunks_exact_mut(n_out))
        {
            unsafe {
                matmul_bf16_vs_f32_avx512(&weight, input_row, output_row, n_in, 0, n_out);
            }
        }

        let mut actual = vec![0.0f32; rows * n_out];
        unsafe {
            matmul_bf16_vs_f32_avx512_tiled(
                &weight,
                &input,
                &mut actual,
                n_in,
                n_out,
                rows,
                0,
                n_out,
            );
        }
        for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
            assert_eq!(a.to_bits(), e.to_bits(), "row {}/{}: tiled={} per-token={}", i % n_out, i / n_out, a, e);
        }
    }
}
